INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Ireland’s first ever Irish Sign Language Café opens in Dublin', 'irelands-first-ever-irish-sign-language-cafe-opens-in-dublin', '<p>The project received €100,000 under the Community Centre Investment Fund (CCIF).</p>
<p>It is hoped that the new facility will create opportunities for employment and remote working, as well as providing members of the Deaf Community with a space to socialise.</p>
<p>Speaking during the visit, Minister Humphreys said: &#8220;This is a very unique, welcoming and inclusive place – a place where members of the Deaf Community can come together and meet up with friends.</p>
<p>&#8220;And it&#8217;s a place too where they can access a range of supports and take part in various different activities and events in areas ranging from sport and education to arts and heritage.</p>
<p>&#8220;But I know too that this Village opens its doors to everyone – and it is a really popular place too for hearing people, our young people and members of the wider Cabra area. I want to commend the work of everyone involved in bringing this project to fruition.&#8221;</p>
<p>Funding under the 2022 Community Centre Investment Fund was available under three categories, with grants of between €10,000 and €300,000 available.</p>
<p>Funding was available for capital works such as improvements to communal facilities, energy retrofitting, or to provide additional services to the community.</p>
<p>Over 860 projects were approved for funding with a combined value of over €45.8 million.</p>', 'Ireland’s first ever Irish Sign Language Café, located in the Deaf Village Ireland premises in Cabra in Dublin, was officially opened by Minister for Rural and Community Development, Heather Humphreys.', 'https://changingireland.ie/wp-content/uploads/2023/12/31A3157.jpg', '', '[{"slug":"community","title":"Community"}]', '[{"slug":"community","title":"Community"},{"slug":"community-cafe","title":"community café"},{"slug":"community-centre","title":"community centre"},{"slug":"community-centre-investment-fund-ccif","title":"Community Centre Investment Fund (CCIF)"},{"slug":"community-development","title":"community development"},{"slug":"deaf-community","title":"Deaf Community"},{"slug":"deaf-village-ireland","title":"Deaf Village Ireland"},{"slug":"department-rural-community-development-drcd","title":"Department of Rural and Community Development"},{"slug":"funding","title":"funding"},{"slug":"irish-sign-language","title":"Irish Sign Language"},{"slug":"irish-sign-language-cafe","title":"Irish Sign Language Café"},{"slug":"minister-heather-humphreys","title":"Minister Heather Humphreys"}]', '', 253640, 1, '2023-12-06T10:55:47Z', '2023-12-05T13:59:00Z', '2023-12-06T10:55:47Z')
