INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Dormant Accounts Fund to provide €47.6 million for disadvantaged communities', 'dormant-accounts-fund-to-provide-e47-6-million-for-disadvantaged-communities', '<p>Minister of State for Community Development, Integration and Charities Joe O&#8217;Brien has revealed that the Dormant Accounts Fund will provide €47.6 million to various initiatives to help disadvantaged communities all over Ireland.</p>
<p>Funding under the 2024 Action Plan has decreased by 12.5% from 2023. A statement from the Department of Rural and Community development said that “further reductions are required in the coming years to sustain the fund”.</p>
<p>The Minister made the announcement while launching the 2024 Dormant Accounts Action Plan recently at the BoxUp project in Rush, Co Dublin.</p>
<p>BoxUp, supported by Sport Ireland through the Dormant Accounts Fund, is an initiative launched this year that aims to tackle inequality in sport by providing free access to sporting equipment.</p>
<p>The Dormant Accounts Fund can be used to fund measures that address economic, social, or educational disadvantage and to support people with a disability.</p>
<p>The 2024 Action Plan allocates funding of €47.6 million to 52 measures to be delivered across 11 Government Departments.</p>
<p>More than €11.3 million has been allocated to the Department of Rural and Community Development: €5.5 million for Rethink Ireland, €2 million for social enterprise measures, €2.7 million for the senior alert scheme, more than €1 million for targeted social inclusion measures, and €150,000 for the promotion of libraries to disadvantaged groups.</p>
<p>Minister O&#8217;Brien said: &#8220;The 52 measures approved for funding in 2024 will be implemented across Government and will help to address a diverse range of issues such as long-term unemployment, Traveller equality, youth disadvantage, migrant integration, and probation supports to prevent reoffending.</p>
<p>&#8220;Dormant Accounts funding makes a real difference to individuals and communities right across the country. The 2024 Action Plan will help ensure that we can continue to support those who need it most during these challenging times. I am particularly pleased to see continued support for Traveller initiatives and services across five Departments.&#8221;</p>
<p>Other examples of measures approved for funding include:</p>
<ul>
<li>€10.5 million for investment and actions aimed at improving participation in sports in disadvantaged communities and for persons with disabilities.</li>
<li>€3.9 million for Traveller initiatives and services across five Departments.</li>
<li>€4 million for youth and community justice services aimed at countering the influence and impacts of crime on young people and in communities.</li>
<li>€2.7 million for youth and family initiatives to provide young people with the soft skills needed to improve employability.</li>
</ul>
<p>The Dormant Accounts Fund Action Plan 2024 is available to view <a href="https://www.gov.ie/en/collection/769773-dormant-accounts-fund-annual-action-plans-and-reports/">here</a>.</p>
<p>&nbsp;</p>
<p>&nbsp;</p>
<p>&nbsp;</p>
<p>&nbsp;</p>
<p>&nbsp;</p>', 'The Dormant Accounts Fund will provide over €11.3 million to the Department of Rural and Community Development for Rethink Ireland, social inclusion, and other measures geared at addressing disadvantage', 'https://changingireland.ie/wp-content/uploads/2023/11/BOX-UP-7.jpg', '', '[{"slug":"funding-programmes","title":"Funding Programmes"}]', '[{"slug":"community-development","title":"community development"},{"slug":"department-rural-community-development-drcd","title":"Department of Rural and Community Development"},{"slug":"disability","title":"Disability"},{"slug":"disadvantage","title":"disadvantage"},{"slug":"disadvantaged-communities","title":"disadvantaged communities"},{"slug":"dormant-accounts-fund","title":"Dormant Accounts Fund"},{"slug":"dormant-accounts-fund-action-plan","title":"Dormant accounts fund action plan"},{"slug":"equality","title":"Equality"},{"slug":"funding","title":"funding"},{"slug":"government-funding","title":"government funding"},{"slug":"integration","title":"integration"},{"slug":"libraries","title":"libraries"},{"slug":"minister-joe-obrien","title":"Minister Joe O''Brien"},{"slug":"probation","title":"probation"},{"slug":"rethink-ireland","title":"ReThink Ireland"},{"slug":"senior-alert-scheme","title":"senior alert scheme"},{"slug":"social-enterprise","title":"social enterprise"},{"slug":"social-inclusion","title":"social inclusion"},{"slug":"sport","title":"sport"},{"slug":"travellers","title":"Travellers"},{"slug":"travelling-community","title":"Travelling Community"},{"slug":"unemployment","title":"unemployment"}]', '', 253625, 1, '2023-12-01T11:16:40Z', '2023-11-24T11:18:46Z', '2023-12-01T11:16:40Z')
