INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Comhairle na nÓg helps young people to address period stigma', 'comhairle-na-nog-helps-young-people-to-address-period-stigma', '<p>The Dublin City Comhairle na nÓg Youth Conference 2023 was held at the Mansion House last week, attended by more than 200 representatives from schools and youth organisations across the city.</p>
<p>Throughout a series of workshops, the Comhairle members discussed a number of themes relevant to them and their daily lives.</p>
<p>Speaking at the opening of the conference, Lord Mayor of Dublin Daithí de Róiste said, &#8220;This event is a stepping stone for our youth, an opportunity to become part of the next generation of leaders in Dublin City.</p>
<p>“Comhairle na nÓg gives young people a voice in the decision-making in the development of local services and policies. It gives young people a chance to shape their own future and not have others decide it for them. It&#8217;s very important that we hear from them.&#8221;</p>
<p>The young people, aged from 12 to 17 years of age also discussed the work carried out by Comhairle during the previous year.</p>
<p>Since the 2022 conference, the elected Comhairle members had worked on raising awareness of period stigma. As part of their work programme, the members arranged free period packs to be distributed to all members&#8217; schools across Dublin City.</p>
<p>Members of Dublin City Comhairle na nÓg also took part in a short film, &#8216;Talking Heads&#8217;, to voice their opinion on the topic of period stigma and contribute their views on Irish society.</p>
<p>&#8220;Comhairle&#8217;s success would not be possible without the continuous support and encouragement given by parents, schools and youth organisations.  While Dublin City Council facilitates the overall organisation of Comhairle in the city area, it does this through a multi-agency approach with partner organisations relevant to young people and their areas of interest.</p>
<p>“By giving the youth this chance to discuss and debate important matters of relevance to them in their community, they are encouraged to speak out and be heard as an influential voice in the local and national decision-making processes.&#8221; said Christine Lyons, Comhairle co-ordinator, Dublin City Council.</p>
<p>&nbsp;</p>', 'Members distributed free period packs to schools across Dublin City, the annual Dublin City Comhairle na nÓg Youth Conference heard.', 'https://changingireland.ie/wp-content/uploads/2023/11/Image1.jpg', '', '[{"slug":"empowerment","title":"Empowerment"}]', '[{"slug":"comhairle-na-nog","title":"Comhairle na nÓg"},{"slug":"dublin-city-comhairle-na-nog","title":"Dublin City Comhairle na nÓg"},{"slug":"dublin-city-council","title":"Dublin City Council"},{"slug":"lord-mayor-of-dublin-daithi-de-roiste","title":"Lord Mayor of Dublin Daithi de Róiste"},{"slug":"mansion-house","title":"Mansion House"},{"slug":"period-stigma","title":"period stigma"},{"slug":"youthwork","title":"Youthwork"}]', '', 253620, 1, '2023-11-27T10:45:17Z', '2023-11-27T10:45:07Z', '2023-11-27T10:45:17Z')
