INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Circular economy keeps the world going round', 'circular-economy-will-keep-the-world-going-round', '<p>The economic model recognises that the Earth’s resources are finite, and that like in nature, there should be no waste – everything should be transformed into materials and products that can be used again.</p>
<p>Our current economic system is largely linear; natural resources are used to create products that are then used and thrown away. The circular economy ties in with the zero carbon movement, and aims to cut down on manufacturing, keep products in use for as long as possible, and reduce waste.</p>
<p>It does this through recycling, upcycling, repairing and reusing items, as well as sustainable design principles, and business models that offer products to share or rent rather than a one-off purchase.</p>
<p>Internationally, governments are beginning to recognise the importance of the circular economy model. Circular principles are central to the EU’s Industrial Strategy and the EU Green Deal, and Ireland’s first national circular economy strategy was launched in December 2021. A total of €110 million was allocated to the development of Ireland&#8217;s circular economy under Budget 2024.</p>
<p>Ireland’s National Centre for the Circular Economy is located at the Rediscovery Centre in the repurposed Boiler House in Ballymun.</p>
<p>Describing itself as “a creative movement connecting people, ideas and resources to support greener low-carbon living”, the Rediscovery Centre brings together artists, scientists, designers and craftspeople through the common goal of promoting sustainability.</p>
<p>The centre also houses four circular economy social enterprises: Rediscover Furniture, Rediscover Fashion, Rediscover Paint and Rediscover Cycling.</p>
<p>It offers workshops and conducts research activities that support national waste prevention and climate action policies.</p>
<p>The Rediscovery Centre also houses an Eco Store selling sustainably made products from its own social enterprises, and more than 20 other independent Irish suppliers.</p>
<p>&nbsp;</p>', 'Circular Week 2023 is currently taking place from October 23-27 to help promote sustainable business practices. The circular economy may be a relatively new term to most people, but it is a concept that has been around since the turn of the century.', 'https://changingireland.ie/wp-content/uploads/2023/10/rediscovery-centre-scaled.jpg', '', '[{"slug":"enterprise","title":"Enterprise"}]', '[{"slug":"ballymun","title":"Ballymun"},{"slug":"circular-economy","title":"circular economy"},{"slug":"circular-week-2023","title":"Circular Week 2023"},{"slug":"eu","title":"EU"},{"slug":"eu-green-deal","title":"EU Green Deal"},{"slug":"eu-industrial-strategy","title":"EU Industrial Strategy"},{"slug":"irelands-national-centre-for-the-circular-economy","title":"Ireland''s National Centre for the Circular Economy"},{"slug":"national-circular-economy-strategy","title":"National Circular Economy Strategy"},{"slug":"recycling","title":"recycling"},{"slug":"rediscovery-centre","title":"Rediscovery Centre"},{"slug":"repurposing","title":"repurposing"},{"slug":"sustainability","title":"sustainability"},{"slug":"sustainable-business","title":"sustainable business"}]', '', 253432, 1, '2023-10-25T09:53:47Z', '2023-10-25T10:06:05Z', '2023-10-25T09:53:47Z')
