INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Sixth tranche of funding to assist community and voluntary groups with energy costs', 'sixth-tranche-of-funding-to-assist-community-and-voluntary-groups-with-energy-costs', '<p>A total of 876 groups have now benefited from the scheme, while more than €1.42 million has been disbursed.</p>
<p><span lang="GA">The scheme was launched in response to the rising cost of energy and the impact it is having on the sector. It provides community and voluntary groups with a one-off contribution towards the increased energy costs they faced in 2022. Payments will issue to the organisations immediately.</span><b></b></p>
<p><span lang="GA"> </span><span lang="GA">Among the successful applicants announced today are:</span></p>
<ul type="disc">
<li><b><span lang="GA">Donegal &#8211; Crossroads &amp; Killygordon Enterprise Centre: €4,260</span></b></li>
<li><b><span lang="GA">Dublin – Fettercairn Community and Youth Centre: €7,186</span></b></li>
<li><b><span lang="GA">Roscommon &#8211; TSP Suil Ar Aghai CLG: €3,256</span></b></li>
<li><b><span lang="GA">Whitechurch &amp; Waterloo Community Association CLG: €3,286</span></b></li>
</ul>
<p><span lang="GA">Minister for Rural and Community Development Heather Humphreys said: &#8220;</span><span lang="GA">While the grants may be small in nature, I hope they will give valuable breathing space to groups that form the backbone of our communities, delivering essential services and supports and providing facilities to communities all over Ireland.&#8221;</span></p>
<p><i><span lang="GA"> </span></i><span lang="GA">Minister of State Joe O&#8217;Brien added: </span><span lang="GA">&#8220;This scheme was about ensuring support to community and voluntary organisations of all shapes and sizes that might have fallen through the net of other schemes.  Over the course of the six tranches, the scheme has given tailored assistance to small local halls and to large, national organisations.  I hope that this announcement of funding will help these 30 organisations to continue their vital work.&#8221;</span></p>
<p><span lang="GA">T</span><span lang="GA">he government is also urging householders and businesses to ensure that they are availing of the supports that are in place. For more information on the supports available visit: <a href="https://www.gov.ie/en/campaigns/6ca43-reduce-your-use/" target="_blank" rel="noopener noreferrer">the Reduce Your Use webpage.</a></span></p>
<p><span lang="GA"><a href="https://www.gov.ie/en/collection/08468-community-voluntary-energy-support-scheme-cvess/" target="_blank" rel="noopener noreferrer">Click here for information on the full list of successful applicants.</a></span></p>', 'The sixth and final tranche of funding under the Community and Voluntary Energy Support Scheme (CVESS) is to provide a further €78,000 to 30 community and voluntary organisations with energy costs, it was announced today.', 'https://changingireland.ie/wp-content/uploads/2023/10/image-from-rawpixel-id-6030754-jpeg.jpg', '', '[{"slug":"funding","title":"Funding"}]', '[{"slug":"community-and-voluntary-energy-support-scheme-cvess","title":"Community and Voluntary Energy Support Scheme (CVESS)"},{"slug":"community-and-voluntary-groups","title":"community and voluntary groups"},{"slug":"cost-of-living-crisis","title":"cost-of-living crisis"},{"slug":"department-rural-community-development-drcd","title":"Department of Rural and Community Development"},{"slug":"donegal","title":"Donegal"},{"slug":"dublin","title":"Dublin"},{"slug":"energy-crisis","title":"energy crisis"},{"slug":"minister-heather-humphreys","title":"Minister Heather Humphreys"},{"slug":"minister-joe-obrien","title":"Minister Joe O''Brien"},{"slug":"roscommon","title":"Roscommon"}]', '', 253428, 1, '2023-10-20T11:38:20Z', '2023-10-20T11:38:20Z', '2023-10-20T11:38:20Z')
