INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Ploughing Championships to help promote outdoor recreation, and responsible dog control', 'ploughing-championship-to-help-promote-outdoor-recreation-and-responsible-dog-control', '<p>The sustainable development of outdoor recreation in rural areas will be a key focus for the Department of Rural and Community Development at this year&#8217;s National Ploughing Championships, commencing next Tuesday in Ratheniska, Co. Laois.</p>
<p>While the Department is encouraging people to embrace Ireland&#8217;s outdoors, it is highlighting the need for it to be done in a safe and respectful manner.</p>
<p>The Department&#8217;s exhibit will include Water Safety Ireland demonstrations, advice and support from Rural Recreation Officers and an area focusing on responsible dog ownership.</p>
<p>The Department says the issue of dog attacks on livestock “is of grave concern to the farming community”.</p>
<p>Local authority vets and dog wardens will be at the exhibit discussing the importance of keeping dogs under control, the issues of livestock worrying, the requirement to have a dog licence and general animal welfare.</p>
<p>Minister for Rural and Community Development Heather Humphreys commented: &#8220;Visitors to our exhibit will notice the focus on responsible dog ownership where we will be emphasising the importance of keeping dogs under control in rural areas and dog owners’ responsibilities.</p>
<p>&#8220;We will be reminding attendees of the need to respect landowners’ requests and about where dogs are welcome and where they are not. Attacks by dogs on livestock cause huge emotional and economic harm to our farming families.</p>
<p>&#8220;It is vital that we promote responsible behaviour so everyone can enjoy the countryside without causing harm to farmers’ livelihoods.&#8221;</p>
<p>The Department&#8217;s exhibit, &#8216;Our Rural Future &#8211; Supporting People and Communities&#8217; will be located in the Government of Ireland Village (Block 3, Row 22, Stand 348).</p>
<p>It will also include information on rural and community funding, Public Participation Networks, Volunteer Ireland, coding demonstrations, and more.</p>
<p>In addition, there will be stands from:</p>
<ul>
<li>Unfair Trading Practices,</li>
<li>Revenue Commissioners,</li>
<li>Competition and Consumer Protection Commission,</li>
<li>Workplace Relations Commission,</li>
<li>Department of Social Protection, and</li>
<li>Health Insurance Authority.</li>
</ul>
<p>For further information visit <a href="http://www.gov.ie/ploughing">gov.ie/ploughing</a></p>
<p>Follow the Department for regular Ploughing updates on <a href="https://twitter.com/DeptRCD">Twitter,</a> <a href="https://www.instagram.com/deptrcd/">Instagram,</a> <a href="https://www.facebook.com/DeptRuralandCommunityDevelopment">Facebook</a> and <a href="https://www.linkedin.com/company/drcd/">LinkedIn</a></p>
<p>&nbsp;</p>', 'An eight-metre climbing tower, robotics demos, and a mobile library are just some of the attractions promised at the ‘Our Rural Future – Supporting People and Communities’ exhibit.', 'https://changingireland.ie/wp-content/uploads/2022/09/LEADER-DRCD-staff-member-with-Min-HH-127-scaled.jpg', '', '[{"slug":"events","title":"Events"}]', '[{"slug":"agriculture","title":"agriculture"},{"slug":"community-development","title":"community development"},{"slug":"competition-and-consumer-protection-commission","title":"Competition and Consumer Protection Commission"},{"slug":"department-rural-community-development-drcd","title":"Department of Rural and Community Development"},{"slug":"department-of-social-protection-dsp","title":"Department of Social Protection (DSP)"},{"slug":"dog-control","title":"Dog control"},{"slug":"farming","title":"farming"},{"slug":"health-insurance-authority","title":"Health Insurance Authority"},{"slug":"laois","title":"Laois"},{"slug":"livestock","title":"livestock"},{"slug":"minister-heather-humphreys","title":"Minister Heather Humphreys"},{"slug":"national-ploughing-championships","title":"National Ploughing Championships"},{"slug":"outdoor-recreation","title":"outdoor recreation"},{"slug":"ppn","title":"PPN"},{"slug":"public-participation-networks","title":"Public Participation Networks"},{"slug":"ratheniska","title":"Ratheniska"},{"slug":"revenue-commissioners","title":"Revenue Commissioners"},{"slug":"rural-development","title":"rural development"},{"slug":"rural-recreation-officer","title":"rural recreation officer"},{"slug":"unfair-trading-practices","title":"Unfair Trading Practices"},{"slug":"water-safety-ireland","title":"Water Safety Ireland"},{"slug":"workplace-relations-commission-wrc","title":"Workplace Relations Commission (WRC)"}]', '', 253398, 1, '2023-09-15T15:56:21Z', '2023-09-15T16:09:38Z', '2023-09-15T15:56:21Z')
