INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Pride of Place is coming to Armagh', 'pride-of-place-is-coming-to-armagh', '<p>Hundreds of delegates from across the island of Ireland are expected to travel for the awards, which will name the winners of the annual competition organised by peacebuilding charity Co-operation Ireland and sponsored by IPB Insurance.</p>
<p>Established to promote and celebrate the best in community development, the awards recognise the selfless efforts of people in making their local neighbourhoods better places to live, work and socialise.</p>
<p>Pride of Place is an all-island competition, which sees local authorities nominate groups in their communities who they feel have made a significant contribution to improving their neighbourhood, working collectively.</p>
<p>The competition culminates with a Gala Awards Ceremony.</p>
<p>2023 marks the 21<sup>st</sup> year of the awards and the ceremony will be hosted by UTV’s Pamela Ballantine.</p>
<p>Speaking at the launch at The Palace Demesne this week<strong>, </strong>Lord Mayor of Armagh City, Banbridge and Craigavon, Alderman Margaret Tinsley said: “We are delighted to host this year’s Pride of Place Awards Ceremony and we look forward to bringing community groups together, to recognise and celebrate the valuable impact volunteers make to community life. I’m looking forward to welcoming everyone to the historic city of Armagh as a special award evening awaits our wonderful guests.”</p>
<p>Peter Sheridan, chief executive officer, Co-operation Ireland added: “Co-operation Ireland is incredibly proud to be a part of Pride of Place as the awards enter their third decade.</p>
<p>“We work to build relationships across the island and Pride of Place plays a critical role in that work.  The impact the awards have had in towns and villages across the island since 2003 cannot be underestimated, and the continuing success of the awards is down to the dedicated volunteers and their love of where they live.”</p>', 'Pride of Place, Ireland’s largest community awards will be hosted by Armagh, Banbridge and Craigavon Borough Council on Friday, November 10 at the Armagh City Hotel.', 'https://changingireland.ie/wp-content/uploads/2023/09/pride-of-place2.jpg', '', '[{"slug":"community","title":"Community"}]', '[]', '', 253394, 1, '2023-09-13T13:40:32Z', '2023-09-13T13:40:32Z', '2023-09-13T13:40:32Z')
