INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('The countdown is on to Make Way Day', 'the-countdown-is-on-to-make-way-day', '<p>Disability groups and activitists and local organisations around the country will be out and about highlighting obstacles and potential hazards on footpaths such as: illegally parked cars and vans blocking footpaths, bicycles or motorcycles chained to lamp posts that can create a trip hazard for a visually impaired person, illegally-placed sandwich boards, bins, barrels and other obstructions.</p>
<p>The Disability Federation of Ireland will also be carrying out an online survey again this year to gather information on the obstacles that people meet on their streets. The tool will be available on the Make Way Day website &#8211; <a href="http://elink.disability-federation.__NArAh6dAaNgc5DJPoRVA">www.makewayday.com</a>.</p>
<p>For updates on the campaign, follow #MakeWayDay23 on social media or go to <a href="http://elink.disability-federation._">www.disability-federation.ie</a>.</p>', 'People with disabilities will be taking to the streets on Friday, September 22 for Make Way Day, an annual campaign to raise public awareness about the problems caused by obstacles blocking footpaths.', 'https://changingireland.ie/wp-content/uploads/2023/09/16926322011351324_md.jpg', '', '[{"slug":"inclusion","title":"Inclusion"}]', '[{"slug":"accessibility","title":"accessibility"},{"slug":"disabilities","title":"disabilities"},{"slug":"disability-activist","title":"disability activist"},{"slug":"disability-federation-of-ireland-dfi","title":"Disability Federation of Ireland (DFI)"},{"slug":"disability-organisations","title":"disability organisations"},{"slug":"disability-rights","title":"disability rights"},{"slug":"make-way-day","title":"Make Way Day"},{"slug":"pedestrian-safety","title":"pedestrian safety"},{"slug":"road-safety","title":"road safety"},{"slug":"safety","title":"safety"}]', '', 253390, 1, '2023-09-11T10:41:07Z', '2023-09-08T10:41:21Z', '2023-09-11T10:41:07Z')
