INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Culture Night is back and it’s turning 18', 'culture-night-is-back-and-its-turning-18', '<p>Organisers say: “Culture Night is about opening doors and inviting people in to experience a range of quality arts and cultural events for free. It is a chance for each one of us to connect with the arts and experience something new. Over the years special attention has been given to creating spaces that are inclusive and safe.</p>
<p>“Culture Night celebrates belonging and is for everyone, so no matter what your age or inclination, go check out the Culture Night programme (<a href="https://culturenight.ie/events/">https://culturenight.ie/events/</a>) to see what free events are happening in your area.”</p>
<p>Culture Night was conceived by Temple Bar Cultural Trust in 2006.</p>
<p>The initial intention with the project was to connect various cultural spaces in Dublin and open them up to later audiences.</p>
<p>During its first year, 40 cultural institutions took part. Now, stewarded by the Arts Council in collaboration with local authority arts offices, the initiative has grown into one of the country’s largest free cultural events.</p>
<p>Accessible events that are family-friendly and suitable for all ages have always been a priority for Culture Night, and this year is no different with a packed programme featuring something for everyone.</p>
<p>Culture Night Late is also back for its second year, thanks to an Arts Council funding programme of the same name. The fund was conceived as part of the Night-Time Economy Support Scheme, which was developed by The Department of Tourism, Culture, Arts, Gaeltacht, Sport and Media in 2022.</p>
<p>The Culture Night Late programme includes cabaret in Cork, a pop-up Gaeltacht in Galway, and a discussion on Buddhist sacred spaces in Dublin.</p>
<p>For those unable to take part in Culture Night due to illness, Read Mór, the Arts Council’s book-gifting project, will gift books from a list of 30 Irish titles to patients in seven hospitals around the country.</p>
<p>RTÉ will also stage a number of live broadcasts at various events nationwide.</p>
<p>For more information on Culture Night, go to www.culturenight.ie</p>
<p>&nbsp;</p>', 'Culture Night, the annual nationwide celebration of culture and the arts in Ireland, returns on September 22 for its 18th year, with a full programme of events for all ages and interests.', 'https://changingireland.ie/wp-content/uploads/2023/09/Culture-Night-0016-1536x1024-1.jpg', '', '[{"slug":"events","title":"Events"}]', '[{"slug":"arts","title":"Arts"},{"slug":"cork","title":"Cork"},{"slug":"culture","title":"culture"},{"slug":"culture-night","title":"Culture Night"},{"slug":"culture-night-late","title":"Culture Night Late"},{"slug":"department-of-tourism","title":"Department of Tourism"},{"slug":"department-of-tourism-culture-arts-gaeltacht-sport-and-media","title":"Department of Tourism Culture Arts Gaeltacht Sport and Media"},{"slug":"dublin","title":"Dublin"},{"slug":"gaeltacht","title":"Gaeltacht"},{"slug":"galway","title":"Galway"},{"slug":"local-authorities","title":"local authorities"},{"slug":"night-time-economy-support-scheme","title":"Night-Time Economy Support Scheme"},{"slug":"sport-and-media","title":"Sport and Media"},{"slug":"temple-bar-cultural-trust","title":"Temple Bar Cultural Trust"},{"slug":"the-arts-council","title":"The Arts Council"}]', '', 253385, 1, '2023-09-08T09:53:40Z', '2023-09-08T09:52:41Z', '2023-09-08T09:53:40Z')
