INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Join the Climate Conversation to have your say on the future of the environment', 'join-the-climate-conversation-to-have-your-say-on-the-future-of-the-environment', '<p>According to the Department: “Government, communities, industry and individuals each have a part to play to help Ireland shift to a carbon-neutral future.</p>
<p>“The government want to hear how they can engage, enable and empower people to take action and realise the potential of moving towards carbon neutrality. Becoming a climate resilient society will help us to cope with the impacts of a changing climate and we are committed to achieving this future through a just transition, meaning all voices will be heard in a fair and equal manner, and new opportunities will mean no one is left behind.”</p>
<p>Climate Conversations 2023 will help to inform the Climate Action Plan 2024.</p>
<p>The Plan’s purpose is to set out a roadmap for meeting Ireland&#8217;s 2021-2025 legally binding carbon budget, that is, the total amount of emissions that may be emitted in the State during a five-year period.</p>
<p>Ireland remains the third worst emitter of greenhouse gas emissions in Europe.</p>
<p>The latest projections by the Environmental Protection Agency and An Taisce show that Ireland will fall significantly short of its 2030 legally binding emissions reduction targets.</p>
<p>An <a href="https://communityworkireland.us14.list-manage.com/track/click?u=f9396b10cc05b70c128f75334&amp;id=6e36ec9cd6&amp;e=3895580dba">online questionnaire</a> is now open where people can give their views on shopping, reuse and recycling, food and food waste, heating our homes and sustainable living, local environment and climate change.</p>
<p>The closing date for submissions is 5.30pm this Friday, September 8.</p>
<p>Anyone with any queries about the questionnaire can email <u><a href="mailto:ClimateConversation@decc.gov.ie">ClimateConversation@decc</a>.gov.ie</u></p>
<p>&nbsp;</p>', 'The Department of Environment, Climate and Communications has launched the Climate Conversation 2023, a forum that gives members of the public the chance to share their thoughts on climate action.', 'https://changingireland.ie/wp-content/uploads/2021/02/Flat-Earth-from-space-courtesy-of-the-BBC-2.jpg', '', '[{"slug":"climate-justice","title":"Climate Justice"}]', '[{"slug":"an-taisce","title":"An Taisce"},{"slug":"carbon-emissions","title":"carbon emissions"},{"slug":"carbon-neutral","title":"carbon neutral"},{"slug":"climate-action","title":"climate action"},{"slug":"climate-action-plan","title":"Climate Action Plan"},{"slug":"climate-and-communications","title":"Climate and Communications"},{"slug":"climate-change","title":"climate change"},{"slug":"climate-conversations","title":"Climate Conversations"},{"slug":"department-of-the-environment","title":"Department of the Environment"},{"slug":"environment","title":"Environment"},{"slug":"epa-environmental-protection-agency","title":"EPA Environmental Protection Agency"},{"slug":"europe","title":"Europe"},{"slug":"govenment","title":"govenment"},{"slug":"greenhouse-gases","title":"greenhouse gases"},{"slug":"ireland","title":"Ireland"},{"slug":"irish-government","title":"Irish government"}]', '', 253383, 1, '2023-09-07T13:29:41Z', '2023-09-07T13:29:41Z', '2023-09-07T13:29:41Z')
