INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('End Child Poverty Week – Call for Budget 2024 to be “Children’s Budget”', 'end-child-poverty-week-call-for-budget-2024-to-be-childrens-budget', '<p>The week will place a spotlight on key thematic areas of child poverty, including early years, education, income, national action and local plans, child welfare and alternative care.</p>
<p>Ahead of the launch of Budget 2024 on October 10, the Children&#8217;s Rights Alliance is calling for “a Children&#8217;s Budget” &#8211; one that is designed to break the cycle of poverty affecting children, young people and families across the country.</p>
<p>Speaking in response to the publication of the Government’s Child Poverty and Wellbeing Unit Programme Plan earlier this month, Tanya Ward, Chief Executive of the Children’s Rights Alliance said:</p>
<p>&#8220;In the past few weeks, we have seen the publication of several seismic reports into children’s care and wellbeing along with a further increase in the number of children experiencing homelessness in Ireland.</p>
<p>“We need to see ambitious thinking and significant and strategic investment in children and young people to break the cycle of poverty that holds them back from reaching their full potential.</p>
<p>“Child poverty affects every aspect of a child’s life and the longer a child lives with the weight of poverty on their shoulders, the greater the risk of it casting a shadow over the rest of their future.”</p>
<p>Each day during End Child Poverty Week 2023, a event featuring a keynote speaker and expert panel discussion will take place both in person and online focusing on the each of the key themes.</p>
<p>Keynote speakers throughout the week include Senator Lynn Ruane; psychologist Dr Sharon Lambert; assistant secretary general for social policy, Elizabeth Canavan; social studies professor Hugh Frazer; and Professor Mathias Urban, of the Early Childhood Research Centre at DCU.</p>
<p>For more information on each of the daily events, or to register to attend online or in person, go to <a href="https://www.childrensrights.ie/content/end-child-poverty-week">https://www.childrensrights.ie/content/end-child-poverty-week</a>.</p>', 'End Child Poverty Week takes place this year from September 11 to 15 to highlight key issues relating to child poverty and the impact on those affected.', 'https://changingireland.ie/wp-content/uploads/2023/08/1500x500.jpeg', '', '[{"slug":"policy-strategy","title":"Policy & Strategy"}]', '[{"slug":"budget-2024","title":"Budget 2024"},{"slug":"child-poverty","title":"child poverty"},{"slug":"child-welfare","title":"child welfare"},{"slug":"childrens-right-alliance","title":"Children''s Right Alliance"},{"slug":"education","title":"education"},{"slug":"end-child-poverty-week-2023","title":"End Child Poverty Week 2023"},{"slug":"funding","title":"funding"},{"slug":"income","title":"income"},{"slug":"senator-lynn-ruane","title":"Senator Lynn Ruane"},{"slug":"tanya-ward-ceo-childrens-rights-alliance","title":"Tanya Ward CEO Children''s Rights Alliance"}]', '', 253380, 1, '2023-08-31T11:13:40Z', '2023-08-31T11:13:40Z', '2023-08-31T11:13:40Z')
