INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('First Local Action Groups to deliver LEADER 2023-2027 funding announced', 'first-local-action-groups-to-deliver-leader-2023-2027-funding-announced', '<p>The LEADER programme promises to provide €180 million to support rural communities and enterprises between 2023 and 2027.</p>
<p>Carlow and Tipperary LAGs are the first two approved from an ongoing process to select the LAGs that will deliver this funding throughout rural Ireland.</p>
<p>The LAG in Carlow is led by the Local Community Development Committee (LCDC) in partnership with County Carlow Development Partnership and Carlow County Council and will receive €4.9 million in funding to support a range of activities in the county.</p>
<p>The LAG in Tipperary is led by the Tipperary LCDC in partnership with North Tipperary Development Company, South Tipperary Development Company and Tipperary County Council and will receive €7.8 million in funding to deliver its strategy.</p>
<p>South Tipperary Development Company commented on social media: &#8220;Delighted that Tipp is one of the the first two areas approved for the new LEADER Programme. Looking forward to working with communities and enterprises in the years ahead with our partners Tipperary LCDC, <span>North Tipperary Development Company,</span> and <span>Tipperary County Council.&#8221;</span></p>
<p>Speaking at today&#8217;s announcement, Minister for Rural and Community Development Heather Humphreys said: The LEADER Programme is based on a community-led, bottom-up approach to rural development right across the country. It plays an important role in supporting communities and enterprises in progressing job creation, social inclusion and environmental projects at local level.</p>
<p>&#8220;I look forward to seeing the impact of the implementation of the 2023-2027 programme and to ensuring that LEADER continues to play a central role in supporting rural communities into the future. As Local Development Strategies are approved across individual LEADER sub-regional areas, the LAGs can commence the process of seeking and approving applications for funding from communities.&#8221;</p>
<p>Further details of the appointment LAGs for the remaining sub-regional areas will be announced over the coming months as their local development strategies are approved.</p>
<p>The LEADER programme is co-funded by the EU under Ireland&#8217;s Common Agricultural Policy.</p>
<p>&nbsp;</p>', 'Local Action Groups in counties Carlow and Tipperary were announced today as the first two local development strategies (LDS) approved to deliver the 2023-2027 LEADER programme.', 'https://changingireland.ie/wp-content/uploads/2023/08/370173355_251068837886433_107957160250043468_n.jpg', '', '[{"slug":"policy-strategy","title":"Policy & Strategy"}]', '[{"slug":"carlow","title":"Carlow"},{"slug":"carlow-county-council","title":"Carlow County Council"},{"slug":"common-agricultural-policy","title":"Common Agricultural Policy"},{"slug":"community-development","title":"community development"},{"slug":"county-carlow-development-partnership","title":"County Carlow Development Partnership"},{"slug":"department-rural-community-development-drcd","title":"Department of Rural and Community Development"},{"slug":"european-union-eu","title":"European Union EU"},{"slug":"funding","title":"funding"},{"slug":"leader","title":"LEADER"},{"slug":"local-action-groups","title":"Local Action Groups"},{"slug":"local-community-development-committee-lcdc","title":"Local Community Development Committee LCDC"},{"slug":"local-development-strategies","title":"Local development strategies"},{"slug":"minister-heather-humphreys","title":"Minister Heather Humphreys"},{"slug":"north-tipperary-development-company","title":"North Tipperary Development Company"},{"slug":"rural-development","title":"rural development"},{"slug":"south-tipperary-development-clg","title":"South Tipperary Development CLG"},{"slug":"tipperary","title":"Tipperary"},{"slug":"tipperary-county-council","title":"Tipperary County Council"}]', '', 253377, 1, '2023-08-30T17:31:16Z', '2023-08-30T17:32:06Z', '2023-08-30T17:31:16Z')
