INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('€3.5 million funding to maintain drugs services as C&V sector pay crisis continues', 'e3-5-million-funding-to-maintain-drugs-services-as-cv-sector-pay-crisis-continues', '<p>Minister for State for Public Health, Wellbeing and the National Drugs Strategy, Hildegarde Naughton announced this week that the funding will be distributed by community healthcare organisations (CHOs), based on guidance issued by the Department of Health.</p>
<p>Just last month, the Local Drug and Alcohol Task Forces (LDATFs) chairs network warned that community drug task forces were being forced to turn people away due to a staffing crisis in the sector.</p>
<p>The organisation said the task forces were unable to fill vital roles as potential employees instead opted for similar positions at the HSE with higher pay and benefits such as pensions.</p>
<p>The group stated that the sector was struggling due to a funding shortfall and an increased workload, largely driven by an almost 400% rise in the use of crack cocaine.</p>
<p>Ahead of a meeting in Dublin last month, the LDATF chairs network said it needed a €3 million increase in funding in Budget 2024.</p>
<p>Earlier this year, Changing Ireland reported on the recruitment and retention crisis in the community and voluntary sector, with The Wheel CEO Ivan Cooper stating that there was a pay disparity of 12-15 per cent compared with similar roles in the HSE.</p>
<p>He also stated that there were more than 1,000 unfilled posts in the sector.</p>
<p>The crisis continues as up to 5,000 workers in Section 39 community and voluntary organisations nationwide are expected to ballot on industrial action on September 4.</p>
<p>A SIPTU Health Division message sent to members this week said there had been a breakdown in talks between government departments and unions regarding “pay justice” for staff of state-funded Section 39 services.</p>
<p>&nbsp;</p>
<p>&nbsp;</p>', 'A total of €3.5 million in government funding has been granted to help maintain the existing level of drugs and inclusion health services provided by community and voluntary organisations.', 'https://changingireland.ie/wp-content/uploads/2019/08/money-1005477_1280.jpg', '50 euro notes', '[{"slug":"income-employment","title":"Income & Employment"}]', '[{"slug":"budget-2024","title":"Budget 2024"},{"slug":"community-and-voluntary-sector","title":"Community and Voluntary sector"},{"slug":"community-healthcare-organisations-chos","title":"community healthcare organisations (CHOs)"},{"slug":"department-of-health","title":"Department of Health"},{"slug":"funding","title":"funding"},{"slug":"hildegarde-naughton","title":"Hildegarde Naughton"},{"slug":"hse-health-service-executive","title":"HSE"},{"slug":"ivan-cooper","title":"Ivan Cooper"},{"slug":"ldatf-chairs-network","title":"LDATF chairs network"},{"slug":"local-drug-and-alcohol-task-forces-ldatfs","title":"Local Drug and Alcohol Task Forces (LDATFs)"},{"slug":"local-drugs-task-force","title":"Local Drugs Task Force"},{"slug":"minister-for-state-for-public-health","title":"Minister for State for Public Health"},{"slug":"section-39","title":"Section 39"},{"slug":"siptu","title":"siptu"},{"slug":"the-wheel","title":"The Wheel"},{"slug":"wellbeing-and-the-national-drugs-strategy","title":"Wellbeing and the National Drugs Strategy"}]', '', 253372, 1, '2023-08-25T11:39:11Z', '2023-08-25T11:39:11Z', '2023-08-25T11:39:11Z')
