INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Eligible groups urged to apply for PEACEPLUS funding', 'eligible-groups-urged-to-apply-for-peaceplus-funding', '<p><span>A total of €75 million in funding is available for eligible groups in the Re-imaging Communities investment area of Northern Ireland and counties Cavan, Donegal, Leitrim, Louth, Monaghan and Sligo under the programme.</span></p>
<p><span>The funding will support the creation of new builds, or the reimaging, regeneration or transformation of existing spaces, for shared usage. </span></p>
<p><span>The new shared spaces will aim to bring together all communities, while having a transformative effect on the region, creating a lasting legacy within the communities they serve.</span></p>
<p><span><span>The Department is providing funding to support projects under Investment Area 1.4 of the new PEACEPLUS programme: Reimaging Communities, which is 80% funded by the EU.</span><i> </i></span></p>
<p><span>The Department will be partnering with the Department for Communities in Northern Ireland and the Special EU Programmes Body (SEUPB).</span></p>
<p><span><span>A statement from the Department of Rural and Community Development said: “This area of the programme will create a more cohesive society through an increased provision of shared space and services, which will benefit and embed peace and reconciliation.</span></span></p>
<p><span><span>“This will result in more people regularly accessing shared spaces for recreational purposes or to access services. These shared spaces are co-designed on a cross-community basis.</span>”</span></p>
<p><span>Minister for Rural and Community Development, Heather Humphreys commented: “These shared spaces can come in many forms including land, buildings, infrastructure, parks and peace line interface barrier regeneration, and so you need to consider what are the current needs in your area that would have a long-term and lasting impact on everyone involved and benefit society as a whole.</span></p>
<p><span> </span>&#8220;I wish all applicants every success in their endeavours.  Please ensure that you avail of the essential guidance that is available to all potential applicants on the SEUPB&#8217;s website<span>.&#8221;</span></p>
<p><span>The closing date for receipt of applications is 5pm on Thursday September 7.</span></p>
<p><span> </span><span><span>Full details on who is eligible to apply and how to apply for funding under this investment area are available on the SEUPB website </span><a href="https://www.seupb.eu/current-programmes/peaceplus/themes-and-investment-areas/theme-1/14-reimaging-communities" target="_blank" rel="noopener"><span>here</span></a></span></p>
<p><span><span> </span></span></p>', 'Organisations in Northern Ireland and border counties in the Republic are being encouraged to apply for funding to provide shared spaces under the new PEACEPLUS Programme.', 'https://changingireland.ie/wp-content/uploads/2023/08/PEACE_PLUS_Belfast_Workshop_Photo-resized.png', '', '[{"slug":"funding","title":"Funding"}]', '[{"slug":"border-counties","title":"border counties"},{"slug":"cavan","title":"Cavan"},{"slug":"cross-border","title":"cross-border"},{"slug":"department-rural-community-development-drcd","title":"Department of Rural and Community Development"},{"slug":"donegal","title":"Donegal"},{"slug":"eu","title":"EU"},{"slug":"funding","title":"funding"},{"slug":"leitrim","title":"Leitrim"},{"slug":"louth","title":"Louth"},{"slug":"minister-heather-humphreys","title":"Minister Heather Humphreys"},{"slug":"monaghan","title":"Monaghan"},{"slug":"northern-ireland","title":"Northern Ireland"},{"slug":"peaceplus","title":"PEACEPLUS"},{"slug":"sligo","title":"Sligo"},{"slug":"special-eu-programmes-body-seupb","title":"Special EU Programmes Body (SEUPB)"}]', '', 253353, 1, '2023-08-17T11:35:12Z', '2023-08-17T11:35:12Z', '2023-08-17T11:35:12Z')
