INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Honey co-ops could transform Irish landscape and fill producers’ pockets', 'honey-co-ops-could-transform-irish-landscape-and-fill-producers-pockets', '<p>Ireland does not yet have a honey producers’ co-operative, but that could change if farmers listen to Cork students.</p>
<p>A group of UCC students this year set up a hypothetical co-operative to find out if small Irish honey producers would be better off working together, as they do in other countries.</p>
<p>The findings are encouraging and farmers could join the proposed co-op by setting aside land for beehives, earning more income in the process and contributing more to biodiversity.</p>
<p>The hypothetical honey co-op was set up using guidelines from the Irish Co-operative Organisation Society and its aim was to buy honey from co-op members, package it, and create a high value honey brand to be sold. The students found that at least seven people with similar economic needs would need to come together if the proposal was to work.</p>
<p>The test run was conducted by four students from UCC’s Centre of Co- operative Studies who are studying regenerative agriculture, a type of farming that increases biodiversity, enriches soils, improves watersheds and boosts ecosystems.</p>
<h4>Bee Co-Ops common in other countries</h4>
<p>Celia Cremin, Sophie Sibanda, Ignitious Moyo and yours truly found that the success of the honey co-op model depended on whether or not it would give its members a return on their investments. Expected sales generated from 20 hives could amount to €3,314 per year.</p>
<figure aria-describedby="caption-attachment-253284"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2023/07/Laura-Byron-is-studying-for-a-MSc-in-Co-operatives-Agri-Food-and-Sustainable-Development-in-UCC.jpg" alt="" width="780" height="780" srcset="https://changingireland.ie/wp-content/uploads/2023/07/Laura-Byron-is-studying-for-a-MSc-in-Co-operatives-Agri-Food-and-Sustainable-Development-in-UCC.jpg 780w, https://changingireland.ie/wp-content/uploads/2023/07/Laura-Byron-is-studying-for-a-MSc-in-Co-operatives-Agri-Food-and-Sustainable-Development-in-UCC-300x300.jpg 300w, https://changingireland.ie/wp-content/uploads/2023/07/Laura-Byron-is-studying-for-a-MSc-in-Co-operatives-Agri-Food-and-Sustainable-Development-in-UCC-150x150.jpg 150w, https://changingireland.ie/wp-content/uploads/2023/07/Laura-Byron-is-studying-for-a-MSc-in-Co-operatives-Agri-Food-and-Sustainable-Development-in-UCC-768x768.jpg 768w, https://changingireland.ie/wp-content/uploads/2023/07/Laura-Byron-is-studying-for-a-MSc-in-Co-operatives-Agri-Food-and-Sustainable-Development-in-UCC-440x440.jpg 440w, https://changingireland.ie/wp-content/uploads/2023/07/Laura-Byron-is-studying-for-a-MSc-in-Co-operatives-Agri-Food-and-Sustainable-Development-in-UCC-24x24.jpg 24w, https://changingireland.ie/wp-content/uploads/2023/07/Laura-Byron-is-studying-for-a-MSc-in-Co-operatives-Agri-Food-and-Sustainable-Development-in-UCC-48x48.jpg 48w, https://changingireland.ie/wp-content/uploads/2023/07/Laura-Byron-is-studying-for-a-MSc-in-Co-operatives-Agri-Food-and-Sustainable-Development-in-UCC-96x96.jpg 96w" sizes="(max-width: 780px) 100vw, 780px" /><figcaption>&#8211; <em>Laura Byron is studying for a MSc in Co-operatives, Agri-Food and Sustainable Development in UCC</em></figcaption></figure>
<p>“The results of this research may pique the curiosity of farmers and beekeepers alike. In the face of the threats posed by climate change, regenerative agriculture may prove pivotal in securing a sustainable food system for the future,” said Celia.</p>
<p>“Integrating honey production into farming systems would not only enhance soil function and biodiversity, but also provide farmers with an additional source of income. Despite there being multiple thriving cases of honey producer co-operatives in other countries, there has yet one to be formed in Ireland,” she added.</p>
<p>Sophie commented: “There is a shared need in the farming community to address biodiversity decline, and honey production could deliver on this while also providing an additional income support to producers.&#8221;</p>
<p>Regenerative agriculture has amassed a considerable following across the globe, with large corporates like Danone and Nestlé now rewarding farmers who adopt regenerative practices.</p>
<p>Research quoted by the UCC students included 2019 data from the Food and Agricultural Organisation of the United Nations highlighting the role played by pollinators and how honeybees in particular can help regenerate land and are an indicator of environmental health. Their decline is often a sign of wider environmental problems.</p>
<p>The students proposed that farmers who dedicate land for honey could become co-op members. Beekeepers would also be welcome.</p>
<p>The students are convinced that co-operative business ideas have the potential to advance regenerative agriculture in Ireland.</p>
<p>• Laura’s article summarises findings from an academic assignment she wrote titled ‘Sweet Partnership: Honeybees, Regenerative Agriculture, and the Co-operative Business Model’.<br />
• For more on UCC’s Centre for Co-operative Studies, visit: https://www.ucc.ie/en/ccs/<br />
• Twitter: @UCCCoopStudies. Also on Facebook and Linkedin.</p>
<p>&nbsp;</p>', 'UCC students’ modelling shows the potential, says Laura Byron, who is studying for a MSc in Co-operatives, Agri-Food and Sustainable Development in UCC.', 'https://changingireland.ie/wp-content/uploads/2023/07/bee2-400x240-1.jpg', '', '[{"slug":"enterprise","title":"Enterprise"}]', '[{"slug":"beehives","title":"beehives"},{"slug":"bees","title":"bees"},{"slug":"biodiversity","title":"Biodiversity"},{"slug":"cooperatives","title":"co-operatives"},{"slug":"cork","title":"Cork"},{"slug":"danone","title":"Danone"},{"slug":"farming","title":"farming"},{"slug":"honey","title":"Honey"},{"slug":"honey-production","title":"honey production"},{"slug":"honeybees","title":"honeybees"},{"slug":"irish-co-operative-organisation-society","title":"Irish Co-operative Organisation Society"},{"slug":"nestle","title":"Nestlé"},{"slug":"polinators","title":"polinators"},{"slug":"regenerative-agriculture","title":"regenerative agriculture"},{"slug":"ucc","title":"UCC"},{"slug":"ucc-centre-of-co-operative-studies","title":"UCC Centre of Co- operative Studies"},{"slug":"university-college-cork","title":"University College Cork"}]', '', 253283, 1, '2023-07-31T11:37:32Z', '2023-07-31T16:05:32Z', '2023-07-31T11:37:32Z')
