INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('New bursary to help community workers gain qualifications', 'new-bursary-to-help-community-workers-gain-qualifications', '<p>The Department of Rural and Community Development (DRCD) has provided the funding for the bursary to the All Ireland Endorsement Body (AIEB) for Community Work Education.</p>
<p>The fund was established to meet a commitment under the government&#8217;s five-year strategy for the Community and Voluntary sector: Sustainable, Inclusive and Empowered Communities.</p>
<p>An AIEB assessment of education and training needs had previously called for affordable and accessible professional community work education for people with degrees already employed in community work jobs.</p>
<p>The bursary will be available to managers of community organisations, community workers and those who undertake community work duties in associated roles who have graduate degrees but no professional community work qualifications.</p>
<p>It will fund places on the Masters in Community and Youth Work Programme at Maynooth University, which will be offered on a part-time basis.</p>
<p>AIEB is also currently developing a pre-professional training initiative for people with no qualifications.</p>
<p>Minister for Integration, Community Development and Charities Joe O&#8217;Brien said: “The bursary will support successful applicants and we hope that employers in the sector will also support their staff to take up this opportunity.</p>
<p>&#8220;My department is currently engaging with AIEB on further proposals to support people employed and involved in community work who do not have any qualifications.”</p>
<p>Information about the bursaries is available from <a href="mailto:bursary@aieb.ie">bursary@aieb.ie</a>. For information about the programme, contact the Department of Applied Social Studies in Maynooth University.</p>
<p>&nbsp;</p>', 'A new bursary fund of €200,000 was launched today to support community workers seeking to pursue endorsed postgraduate community work qualifications.', 'https://changingireland.ie/wp-content/uploads/2023/07/F2H-ujEWkAAysiH.jpeg', '', '[{"slug":"education-training","title":"Education & Training"}]', '[{"slug":"all-ireland-endorsement-body-aieb","title":"All Ireland Endorsement Body AIEB"},{"slug":"community-and-voluntary-sector","title":"Community and Voluntary sector"},{"slug":"community-work","title":"community work"},{"slug":"community-workers","title":"community workers"},{"slug":"department-of-rural-and-community-development-drcd","title":"Department of Rural and Community Development (DRCD)"},{"slug":"maynooth-university","title":"Maynooth University"},{"slug":"minister-joe-obrien","title":"Minister Joe O''Brien"},{"slug":"postgraduate","title":"postgraduate"},{"slug":"youth-work","title":"youth work"}]', '', 253328, 1, '2023-07-28T15:00:42Z', '2023-07-28T15:00:42Z', '2023-07-28T15:00:42Z')
